// ─── File: CollabDemo.java ───
// Runnable demo of OT and CRDT merging the SAME concurrent edits.
// Each class would be its own file in a real project.
package com.bank.collab;

import java.util.*;
import java.util.logging.*;

public class CollabDemo {
    private static final Logger log = Logger.getLogger(CollabDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Starting document shared by Rajesh and Priya
        String base = "Loan amount Rs";
        log.info("Base document: \"" + base + "\"");

        // Concurrent edits:
        //  Rajesh inserts "Home " at position 0  → "Home Loan amount Rs"
        //  Priya  inserts ".500000" at end (position 14)
        Operation rajesh = Operation.insert(0, "Home ");
        Operation priya = Operation.insert(14, " 500000");

        // ── OT path ──
        OTEngine ot = new OTEngine();
        String otDocA = ot.apply(base, rajesh);                 // server applies Rajesh first
        Operation priyaT = ot.transform(priya, rajesh);          // transform Priya against Rajesh
        String otResult = ot.apply(otDocA, priyaT);
        log.info("OT converged result:   \"" + otResult + "\"");

        // ── CRDT path ──
        SequenceCrdt crdtRajesh = SequenceCrdt.fromText(base, "R");
        SequenceCrdt crdtPriya = crdtRajesh.copyForSite("P");
        // both edit their own replica concurrently
        crdtRajesh.insertAt(0, "Home ", "R");
        crdtPriya.insertAt(14, " 500000", "P");
        // merge in EITHER order — commutative
        SequenceCrdt merged1 = crdtRajesh.copyForSite("R").merge(crdtPriya);
        SequenceCrdt merged2 = crdtPriya.copyForSite("P").merge(crdtRajesh);
        log.info("CRDT merge (R then P): \"" + merged1.text() + "\"");
        log.info("CRDT merge (P then R): \"" + merged2.text() + "\"");
        log.info("CRDT order-independent: " + merged1.text().equals(merged2.text()));

        // ── Persistence: op log + snapshot ──
        OpLog opLog = new OpLog(1000);
        opLog.append(rajesh); opLog.append(priyaT);
        log.info("OpLog size=" + opLog.size() + " (replay rebuilds document; snapshot every 1000 ops)");

        // ── Offline buffering + replay ──
        OfflineBuffer buffer = new OfflineBuffer();
        buffer.record(Operation.insert(0, "URGENT: "));   // Priya edits offline on a train
        log.info("Offline edits buffered: " + buffer.size() + " → replayed+merged on reconnect");
    }
}

// ─── ot/Operation.java ───
class Operation {
    enum Type { INSERT, DELETE }
    final Type type; final int position; final String text; final int length;
    private Operation(Type t, int pos, String text, int len) {
        this.type = t; this.position = pos; this.text = text; this.length = len;
    }
    static Operation insert(int pos, String text) { return new Operation(Type.INSERT, pos, text, text.length()); }
    static Operation delete(int pos, int len) { return new Operation(Type.DELETE, pos, "", len); }
}

// ─── ot/OTEngine.java ───
// Applies ops and transforms a concurrent op against an already-applied one.
class OTEngine {
    String apply(String doc, Operation op) {
        if (op.type == Operation.Type.INSERT)
            return doc.substring(0, op.position) + op.text + doc.substring(op.position);
        int end = Math.min(doc.length(), op.position + op.length);
        return doc.substring(0, op.position) + doc.substring(end);
    }
    // Transform 'incoming' so it still means the right thing AFTER 'applied' was applied.
    Operation transform(Operation incoming, Operation applied) {
        if (applied.type == Operation.Type.INSERT && incoming.position >= applied.position) {
            int shifted = incoming.position + applied.text.length();   // shift right by inserted length
            return incoming.type == Operation.Type.INSERT
                    ? Operation.insert(shifted, incoming.text)
                    : Operation.delete(shifted, incoming.length);
        }
        if (applied.type == Operation.Type.DELETE && incoming.position > applied.position) {
            int shifted = Math.max(applied.position, incoming.position - applied.length);
            return incoming.type == Operation.Type.INSERT
                    ? Operation.insert(shifted, incoming.text)
                    : Operation.delete(shifted, incoming.length);
        }
        return incoming;   // no overlap → unchanged
    }
}

// ─── crdt/CrdtChar.java ───
// A character with a stable ordered identity (fractional position + site id).
class CrdtChar implements Comparable<CrdtChar> {
    final double pos; final String site; final char ch; boolean deleted = false;
    CrdtChar(double pos, String site, char ch) { this.pos = pos; this.site = site; this.ch = ch; }
    public int compareTo(CrdtChar o) {
        int c = Double.compare(pos, o.pos);
        return c != 0 ? c : site.compareTo(o.site);   // tie-break by site → total order
    }
}

// ─── crdt/SequenceCrdt.java ───
// Sequence CRDT: characters sorted by stable IDs. Merges commutatively.
class SequenceCrdt {
    private final TreeSet<CrdtChar> chars = new TreeSet<>();
    static SequenceCrdt fromText(String text, String site) {
        SequenceCrdt s = new SequenceCrdt();
        for (int i = 0; i < text.length(); i++) s.chars.add(new CrdtChar(i + 1, site, text.charAt(i)));
        return s;
    }
    SequenceCrdt copyForSite(String site) {
        SequenceCrdt s = new SequenceCrdt(); s.chars.addAll(this.chars); return s;
    }
    // Insert text at a visible index by placing IDs between neighbours (fractional positions).
    void insertAt(int visibleIndex, String text, String site) {
        List<CrdtChar> visible = visibleChars();
        double left = visibleIndex == 0 ? 0 : visible.get(visibleIndex - 1).pos;
        double right = visibleIndex >= visible.size() ? left + 1 : visible.get(visibleIndex).pos;
        double step = (right - left) / (text.length() + 1);
        for (int i = 0; i < text.length(); i++)
            chars.add(new CrdtChar(left + step * (i + 1), site, text.charAt(i)));
    }
    SequenceCrdt merge(SequenceCrdt other) { this.chars.addAll(other.chars); return this; }  // commutative union
    private List<CrdtChar> visibleChars() {
        List<CrdtChar> v = new ArrayList<>();
        for (CrdtChar c : chars) if (!c.deleted) v.add(c);
        return v;
    }
    String text() {
        StringBuilder sb = new StringBuilder();
        for (CrdtChar c : chars) if (!c.deleted) sb.append(c.ch);
        return sb.toString();
    }
}

