// Persisted ordered operation log with periodic snapshotting.
class OpLog {
    private final List<Operation> ops = new ArrayList<>(); private final int snapshotEvery;
    OpLog(int snapshotEvery) { this.snapshotEvery = snapshotEvery; }
    void append(Operation op) {
        ops.add(op);
        if (ops.size() % snapshotEvery == 0) snapshot();
    }
    private void snapshot() { /* materialize doc, persist, truncate older ops */ }
    int size() { return ops.size(); }
}

// ─── offline/OfflineBuffer.java ───
class OfflineBuffer {
    private final List<Operation> buffered = new ArrayList<>();
    void record(Operation op) { buffered.add(op); }       // while disconnected
    List<Operation> drainForReplay() { return new ArrayList<>(buffered); }  // on reconnect
    int size() { return buffered.size(); }
}

